async function createSession(){sessionStartError="";state.sessionToken=crypto.randomUUID();const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),10000);try{const r=await fetch(SUPABASE_URL+"/rest/v1/rpc/start_game_session_secure",{method:"POST",signal:controller.signal,headers:{"apikey":SUPABASE_KEY,"Content-Type":"application/json"},body:JSON.stringify({p_game_id:GAME_ID,p_player_name:state.name,p_player_type:state.playerType||"public",p_session_token:state.sessionToken,p_show_in_leaderboard:!!state.showInLeaderboard,p_employee_code:state.playerType==="kuvag"?(state.employeeCode||""):null})});if(!r.ok){const raw=await r.text();try{const x=JSON.parse(raw);sessionStartError=[x.code,x.message,x.details,x.hint].filter(Boolean).join(" — ").slice(0,450)}catch(e){sessionStartError=raw.slice(0,450)}sessionStartError="HTTP "+r.status+": "+sessionStartError;state.sessionToken=null;return false}state.employeeCode=null;return true}catch(e){sessionStartError=e.name==="AbortError"?"Databáze neodpověděla do 10 sekund.":String(e.message||e);state.sessionToken=null;return false}finally{clearTimeout(timeout)}}
