async function renderLeaderboard(){let box=document.querySelector("#leaderboard");if(!box)return;let selected=document.querySelector('input[name="ptype"]:checked'),type=gameInfo.visibility==="kuvag"?"kuvag":gameInfo.visibility==="test"?"test":(selected?selected.value:"public");box.innerHTML='<div class="leaderboard-empty">Načítám TOP 15…</div>';let data=await loadLeaderboard(type);if(!box.isConnected)return;box.innerHTML=data.length?'<div class="leaderboard-table"><div class="leaderboard-row leaderboard-head"><span>#</span><span>Hráč</span><span>Body</span><span>Čas</span></div>'+data.map(x=>'<div class="leaderboard-row"><span>'+x.player_rank+'.</span><span>'+escHtml(x.player_name)+'</span><span>'+x.total_points+'</span><span>'+formatLeaderboardTime(x.duration_seconds)+'</span></div>').join("")+'</div>':'<div class="leaderboard-empty">Zatím tu není žádný dokončený hráč.</div>'}

