function saveProgress(){updateScoreDisplay();if(!state.sessionToken||!state.start)return;try{localStorage.setItem(SAVE_KEY,JSON.stringify({gameId:GAME_ID,sessionToken:state.sessionToken,name:state.name,playerType:state.playerType,i:state.i,score:state.score,hints:state.hints,wrong:state.wrong,start:state.start,hintIndex:state.hintIndex,stationHints:state.stationHints,stationWrong:state.stationWrong,showInLeaderboard:state.showInLeaderboard,navigationUsed:state.navigationUsed,phase:state.phase||"station",secondStage:state.secondStage||1,secondWrong:state.secondWrong||0,testPreview:state.testPreview||null}))}catch(e){console.warn("Uložení hry:",e)}}
