function clearProgress(){try{localStorage.removeItem(SAVE_KEY)}catch(e){}}
async function restoreProgress(){let p;try{p=JSON.parse(localStorage.getItem(SAVE_KEY)||"null")}catch(e){clearProgress();return false}if(!p||p.gameId!==GAME_ID||!p.sessionToken)return false;if(p.playerType==="test"){if(!await loadGameInfo()||!await loadGameStations())return false;Object.assign(state,p,{i:Math.max(0,Math.min(stations.length-1,Number(p.i)||0)),start:Number(p.start)||Date.now(),phase:p.phase||"station"});state.timer=setInterval(tick,1000);tick();if(["reveal","reveal-history","reveal-riddle","reveal-cemetery-history","reveal-cemetery-next"].includes(state.phase))reveal();else if(state.phase==="chapel-route")chapelRiddle();else if(state.phase==="chapel-stone-history")chapelStoneHistory();else if(state.phase==="knarovka-route")knarovkaTransition();else if(state.phase==="post-route")postTransition();else if(state.phase==="roses-route")rosesTransition();else if(state.phase==="square-route")finalSquareTransition();else if(state.phase==="fountain-memory")fountainMemoryQuestion();else if(state.phase==="fountain-mary-reveal")fountainMaryReveal();else if(state.phase==="standard-route-reveal-0")standardRouteReveal();else if(state.phase?.startsWith("standard-route-"))standardTransition(Number(state.phase.slice(-1)));else station(true);saveProgress();return true}if(!await loadGameInfo()||!gameIsPlayable()||!await loadGameStations())return false;let server;try{let r=await fetch(SUPABASE_URL+"/rest/v1/rpc/get_game_state_v2",{method:"POST",headers:{"apikey":SUPABASE_KEY,"Content-Type":"application/json"},body:JSON.stringify({p_session_token:p.sessionToken})});if(!r.ok)throw new Error(await r.text());server=await r.json()}catch(e){console.error("Obnovení serverového stavu:",e);return false}if(!server||Number(server.gameId)!==GAME_ID||server.isFinished){clearProgress();return false}let index=stations.findIndex(st=>String(st.id)===String(server.nextStationId));if(index<0){Object.assign(state,p,{i:stations.length-1,start:Date.parse(server.startedAt),phase:"reveal"});state.timer=setInterval(tick,1000);tick();reveal();return true}let rows=server.progress||[],current=rows.find(x=>String(x.stationId)===String(server.nextStationId))||{};let completed=rows.filter(x=>x.completed),penalty=rows.reduce((n,x)=>n+(x.hints===1?10:x.hints>=2?30:0)+Number(x.wrong||0)*5+(x.navigationUsed?30:0),0);Object.assign(state,p,{i:index,start:Date.parse(server.startedAt),score:Math.max(0,maxScore()-penalty),hints:rows.reduce((n,x)=>n+Number(x.hints||0),0),wrong:rows.reduce((n,x)=>n+Number(x.wrong||0),0),hintIndex:Number(current.hints||0),stationHints:Number(current.hints||0),stationWrong:Number(current.wrong||0),navigationUsed:Object.fromEntries(rows.filter(x=>x.navigationUsed).map(x=>[stations.findIndex(st=>String(st.id)===String(x.stationId)),true])),phase:"station",secondStage:index===1?Math.max(1,Math.min(3,Number(p.secondStage)||1)):1,secondWrong:index===1?Number(p.secondWrong)||0:0});state.score=Math.max(0,state.score-state.secondWrong*5);state.timer=setInterval(tick,1000);tick();if(index>0&&p.phase==="standard-route-"+(index-1)){state.i=index-1;standardTransition(index-1)}else if((index===3||index===4)&&p.phase==="chapel-route"){state.i=3;chapelRiddle()}else if(index===7&&p.phase==="roses-route"){state.i=6;rosesTransition()}else if(index===8&&p.phase==="fountain-memory"){state.i=8;fountainMemoryQuestion()}else if(index===8&&p.phase==="fountain-mary-reveal"){state.i=8;fountainMaryReveal()}else if(index>0&&completed.some(x=>String(x.stationId)===String(stations[index-1].id))&&Number(p.i)===index-1&&p.phase==="reveal"){state.i=index-1;reveal()}else station(true);saveProgress();return true}

function norm(s){return s.trim().toLocaleUpperCase("cs-CZ").normalize("NFD").replace(/[\u0300-\u036f]/g,"")}
function tick(){if(!state.start)return;let s=Math.floor((Date.now()-state.start)/1000);timer.textContent=String(Math.floor(s/60)).padStart(2,"0")+":"+String(s%60).padStart(2,"0")}
async function hydrateWelcome(){let ok=await loadGameInfo();if(!ok){showUnavailable("Hru se nepodařilo načíst.");return false}if(!gameIsPlayable()){showUnavailable(gameInfo.status==="scheduled"?"Tato hra zatím není dostupná. Spustí se v naplánovaném termínu.":"Tato hra momentálně není dostupná.");return false}let stationsOk=await loadGameStations();if(!stationsOk){showUnavailable("Hra je zveřejněná, ale její stanoviště se nepodařilo načíst.");return false}let t=document.querySelector("#welcomeTitle"),d=document.querySelector("#welcomeDescription"),n=document.querySelector("#stationCountLabel"),tm=document.querySelector("#welcomeTime");if(t)t.textContent=gameInfo.title||"Šifrovací hra";if(d&&gameInfo.description)d.textContent=gameInfo.description;if(n)n.textContent=visibleStationCount()+" "+(visibleStationCount()===1?"stanoviště":visibleStationCount()>=2&&visibleStationCount()<=4?"stanoviště":"stanovišť");if(tm)tm.textContent="TRASA 4–5 KM • DOBA HRY 2–3 HODINY";applyAudienceOptions();return true}
